<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { fetchArchive, fetchCalendar, fetchPublicPosts, fetchPublicTags, type ArchiveYear, type Calendar, type PublicPostPage, type PublicTagWithCount } from '@/api/blog'
import EditorialMotif from '@/components/visual/EditorialMotif.vue'

const route=useRoute();const router=useRouter();const posts=ref<PublicPostPage|null>(null);const tags=ref<PublicTagWithCount[]>([]);const calendar=ref<Calendar|null>(null);const archive=ref<ArchiveYear[]>([]);const loading=ref(true);const error=ref(false);const filters=reactive({tag:'',date:'',month:'',page:1});const activeMonth=computed(()=>filters.month)
const timeline=computed(()=>{let previous='';return(posts.value?.items??[]).map(post=>{const d=new Date(post.publishedAt);const year=Number.isNaN(d.getTime())?'':String(d.getFullYear());const monthDay=Number.isNaN(d.getTime())?post.publishedAt:d.toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'}).replace('/','.');const showYear=year!==previous;previous=year;return{post,year,monthDay,showYear}})})
async function loadPosts(){loading.value=true;error.value=false;try{posts.value=await fetchPublicPosts({tag:filters.tag||undefined,date:filters.date||undefined,month:filters.month||undefined,page:filters.page,pageSize:10})}catch{error.value=true}finally{loading.value=false}}
function syncFromQuery(){filters.tag=typeof route.query.tag==='string'?route.query.tag:'';filters.date=typeof route.query.date==='string'?route.query.date:'';filters.month=typeof route.query.month==='string'?route.query.month:'';filters.page=typeof route.query.page==='string'?Math.max(Number(route.query.page)||1,1):1}
function applyFilters(patch:Partial<typeof filters>){Object.assign(filters,patch,{page:1});const query:Record<string,string>={};if(filters.tag)query.tag=filters.tag;if(filters.date)query.date=filters.date;if(filters.month)query.month=filters.month;router.replace({query})}
function selectTag(slug:string){applyFilters({tag:filters.tag===slug?'':slug,date:'',month:''})}function selectDate(date:string){applyFilters({date:filters.date===date?'':date,month:''})}function selectMonth(month:string){applyFilters({month:filters.month===month?'':month,date:''})}
function goPage(page:number){filters.page=page;const query:Record<string,string>={...(route.query as Record<string,string>)};if(page>1)query.page=String(page);else delete query.page;router.replace({query});window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
onMounted(async()=>{syncFromQuery();[tags.value,calendar.value,archive.value]=await Promise.all([fetchPublicTags(),fetchCalendar(filters.month||new Date().toISOString().slice(0,7)),fetchArchive()]);await loadPosts()})
watch(()=>route.query,()=>{syncFromQuery();void loadPosts()});watch(activeMonth,async month=>{calendar.value=await fetchCalendar(month||new Date().toISOString().slice(0,7))})
</script>

<template>
  <section class="blog">
    <header class="blog__hero"><div><p>JOURNAL · THINKING &amp; PRACTICE</p><h1>沿时间沉淀思考，<br>让经验持续生长。</h1></div><aside><strong>{{posts?.total??0}}</strong><span>篇公开文章</span><p>技术实践、学习路径与系统复盘。</p></aside></header>
    <div class="blog__layout"><main class="blog__main">
      <div v-if="filters.tag||filters.date||filters.month" class="blog__active"><span>当前视图</span><button v-if="filters.tag" @click="selectTag(filters.tag)"># {{filters.tag}} ×</button><button v-if="filters.date" @click="selectDate(filters.date)">{{filters.date}} ×</button><button v-if="filters.month" @click="selectMonth(filters.month)">{{filters.month}} ×</button></div>
      <div v-if="loading" class="blog__empty">正在读取时间线…</div><div v-else-if="error" class="blog__empty">加载失败，请稍后重试。</div><div v-else-if="!timeline.length" class="blog__empty">{{filters.tag||filters.date||filters.month?'没有符合条件的文章':'暂无文章'}}</div>
      <ol v-else class="timeline">
        <li v-for="item in timeline" :key="item.post.id" class="timeline__item"><div class="timeline__date"><strong v-if="item.showYear">{{item.year}}</strong><span>{{item.monthDay}}</span></div><i class="timeline__node"/><RouterLink :to="`/blog/${item.post.slug}`" class="timeline-card"><div class="timeline-card__content"><div class="timeline-card__tags"><span v-for="tag in item.post.tags" :key="tag.id">{{tag.name}}</span></div><h2>{{item.post.title}}</h2><p>{{item.post.summary}}</p><footer><time>更新于 {{new Date(item.post.updatedAt).toLocaleDateString('zh-CN')}}</time><strong>阅读全文 <i>→</i></strong></footer></div><div class="timeline-card__cover"><img v-if="item.post.coverUrl" :src="item.post.coverUrl" :alt="item.post.title" loading="lazy"/><EditorialMotif v-else kind="blog" :seed="item.post.title" :label="item.post.title"/></div></RouterLink></li>
      </ol>
      <el-pagination v-if="posts&&posts.total>0" :current-page="filters.page" :page-size="10" :total="posts.total" layout="prev, pager, next" class="blog__pagination" @current-change="goPage"/>
    </main><aside class="blog__sidebar">
      <section v-if="tags.length" class="blog-panel"><div class="blog-panel__head"><span>TOPICS</span><small>{{tags.length}} 个主题</small></div><div class="blog__tags"><button v-for="tag in tags" :key="tag.id" :class="{active:filters.tag===tag.slug}" @click="selectTag(tag.slug)"><span>{{tag.name}}</span><em>{{tag.postCount}}</em></button></div></section>
      <section v-if="archive.length" class="blog-panel"><div class="blog-panel__head"><span>ARCHIVE</span><small>文章归档</small></div><div v-for="year in archive" :key="year.year" class="blog__year"><strong>{{year.year}}</strong><button v-for="month in year.months" :key="month.month" :class="{active:filters.month===month.month}" @click="selectMonth(month.month)"><span>{{month.month.slice(5)}} 月</span><em>{{month.count}}</em></button></div></section>
      <section v-if="calendar?.days.length" class="blog-panel"><div class="blog-panel__head"><span>ACTIVE DAYS</span><small>{{calendar.month}}</small></div><div class="blog__days"><button v-for="day in calendar.days" :key="day.date" :class="{active:filters.date===day.date}" @click="selectDate(day.date)">{{day.date.slice(8)}}<small>{{day.count}}</small></button></div></section>
    </aside></div>
  </section>
</template>

<style scoped>
