solid var(--bg-page);border-radius:50%;background:var(--primary);box-shadow:0 0 0 4px color-mix(in srgb,var(--primary) 14%,transparent)}.timeline-card{display:grid;grid-template-columns:minmax(0,1fr) 180px;min-height:190px;overflow:hidden;border:1px solid var(--border);border-radius:20px;color:var(--text-primary);background:var(--bg-surface);transition:transform 170ms ease,border-color 170ms ease,box-shadow 170ms ease}.timeline-card:hover{border-color:color-mix(in srgb,var(--primary) 42%,var(--border));transform:translateY(-2px);box-shadow:0 17px 38px rgb(0 0 0/.075)}.timeline-card__content{display:flex;min-width:0;flex-direction:column;padding:var(--space-5)}.timeline-card__tags{display:flex;flex-wrap:wrap;gap:6px;min-height:20px}.timeline-card__tags span{color:var(--accent);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em}.timeline-card h2{margin:6px 0 8px;font-size:22px;line-height:1.4}.timeline-card__content>p{display:-webkit-box;overflow:hidden;color:var(--text-secondary);font-size:13px;line-height:1.75;-webkit-box-orient:vertical;-webkit-line-clamp:2}.timeline-card footer{display:flex;align-items:center;justify-content:space-between;gap:var(--space-3);margin-top:auto;padding-top:14px}.timeline-card footer time{color:var(--text-muted);font-size:10px}.timeline-card footer strong{color:var(--primary);font-size:12px}.timeline-card footer i{font-style:normal}.timeline-card__cover{display:grid;overflow:hidden;place-items:center;background:linear-gradient(145deg,color-mix(in srgb,var(--primary) 15%,var(--bg-subtle)),color-mix(in srgb,var(--accent) 10%,var(--bg-surface)))}.timeline-card__cover img{width:100%;height:100%;object-fit:cover;transition:transform 170ms ease}.timeline-card:hover img{transform:scale(1.025)}.timeline-card__cover span{color:color-mix(in srgb,var(--primary) 58%,var(--text-muted));font:700 58px/1 Georgia,serif}.blog__sidebar{position:sticky;top:calc(var(--header-height) + var(--space-6));display:flex;flex-direction:column;gap:var(--space-4)}.blog-panel{padding:var(--space-4);border:1px solid var(--border);border-radius:17px;background:var(--bg-surface)}.blog-panel__head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.blog-panel__head span{color:var(--text-primary);font-size:11px;font-weight:800;letter-spacing:.1em}.blog-panel__head small{color:var(--text-muted);font-size:10px}.blog__tags{display:flex;flex-wrap:wrap;gap:7px}.blog__tags button{display:inline-flex;align-items:center;gap:6px;padding:6px 8px 6px 10px;border:1px solid var(--border);border-radius:999px;color:var(--text-secondary);background:transparent;cursor:pointer;font-size:11px}.blog__tags em,.blog__year em{color:var(--text-muted);font-size:9px;font-style:normal}.blog__tags button:hover,.blog__tags button.active,.blog__year button:hover,.blog__year button.active{border-color:var(--primary);color:var(--primary);background:color-mix(in srgb,var(--primary) 8%,transparent)}.blog__year{display:grid;grid-template-columns:50px 1fr;gap:5px 8px;margin-top:8px}.blog__year>strong{grid-row:1/10;color:var(--primary);font-size:13px}.blog__year button{display:flex;justify-content:space-between;padding:4px 7px;border:1px solid transparent;border-radius:8px;color:var(--text-secondary);background:transparent;cursor:pointer;font-size:11px}.blog__days{display:flex;flex-wrap:wrap;gap:6px}.blog__days button{display:grid;width:36px;height:36px;place-items:center;border:1px solid var(--border);border-radius:10px;color:var(--text-secondary);background:transparent;cursor:pointer;font-size:10px}.blog__days button small{font-size:8px;color:var(--text-muted)}.blog__days button.active,.blog__days button:hover{border-color:var(--primary);color:var(--primary)}.blog__pagination{margin:var(--space-8) 0 0 112px}.blog__empty{margin-left:112px;padding:var(--space-9);border:1px dashed var(--border-strong);border-radius:18px;color:var(--text-muted);text-align:center}@media(prefers-reduced-motion:reduce){.timeline-card,.timeline-card img{transition:none}}@media(max-width:960px){.blog__layout{grid-template-columns:1fr}.blog__sidebar{position:static;display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:680px){.blog__hero{grid-template-columns:1fr}.blog__hero>aside{display:none}.timeline::before{left:7px}.timeline__item{grid-template-columns:16px minmax(0,1fr);gap:10px}.timeline__date{grid-column:2;text-align:left;padding:0}.timeline__date strong,.timeline__date span{display:inline;margin-right:7px}.timeline__node{position:absolute;top:28px;left:2px;margin:0}.timeline-card{grid-column:2;grid-template-columns:1fr}.timeline-card__cover{grid-row:1;min-height:150px;aspect-ratio:16/7}.blog__pagination,.blog__empty{margin-left:26px}.blog__sidebar{grid-template-columns:1fr}}
